    return strs.map(s => `${s.length}#${s}`).join("");
};

var decode = function(s) {
    const res = [];
    let i = 0;
    while (i < s.length) {
        const j = s.indexOf("#", i);
        const len = parseInt(s.substring(i, j), 10);
        res.push(s.substring(j + 1, j + 1 + len));
        i = j + 1 + len;
    }
    return res;
};
